use vstd::prelude::*;

verus! {

fn ones(n: usize) -> (result: Vec<i8>)
    ensures
        // The returned vector has length exactly n
        result.len() == n,
        // Every index i in [0, n) has value 1
        forall |i: usize| i < n ==> result[i] == 1,
        // Any two indices in [0, n) carry equal elements
        forall |i: usize, j: usize| i < n && j < n ==> result[i] == result[j],
        // Every element is strictly positive
        forall |i: usize| i < n ==> result[i] > 0,
{
    let mut res: Vec<i8> = Vec::new();
    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            res.len() == i,
            // All elements so far are 1
            forall |k: usize| k < i ==> res[k] == 1,
    {
        res.push(1);
        i = i + 1;
    }
    res
}

} // end of verus! block

fn main() {
    // Example usage
    let v = ones(5);
    assert!(v.len() == 5);
    for &x in &v {
        assert!(x == 1);
    }
}